create table financial_categories(id uuid primary key,created_at timestamptz not null,updated_at timestamptz not null,tenant_id uuid not null references tenants(id),name varchar(255) not null,type varchar(20) not null,active boolean not null default true);
create table financial_entries(id uuid primary key,created_at timestamptz not null,updated_at timestamptz not null,tenant_id uuid not null references tenants(id),type varchar(20) not null,description varchar(255) not null,client_id uuid references clients(id),project_id uuid references projects(id),proposal_id uuid references proposals(id),category_id uuid references financial_categories(id),counterparty_name varchar(255),total_amount numeric(15,2) not null,issue_date date,competence_date date,status varchar(30) not null,notes text,created_by_id uuid references tenant_users(id),client_visible boolean not null default false,deleted boolean not null default false,deleted_at timestamptz);
create table financial_installments(id uuid primary key,created_at timestamptz not null,updated_at timestamptz not null,financial_entry_id uuid not null references financial_entries(id),installment_number integer not null,description varchar(255),amount numeric(15,2) not null,due_date date not null,status varchar(30) not null,settled_amount numeric(15,2) not null default 0);
create table financial_settlements(id uuid primary key,created_at timestamptz not null,updated_at timestamptz not null,installment_id uuid not null references financial_installments(id),amount numeric(15,2) not null,settlement_date date not null,payment_method varchar(30) not null,description text,created_by_id uuid references tenant_users(id),reversed_at timestamptz,reversed_by_id uuid references tenant_users(id),reversal_reason text);
create index idx_financial_entries_tenant_type on financial_entries(tenant_id,type,status);create index idx_financial_entries_project on financial_entries(project_id);create index idx_financial_installments_due on financial_installments(due_date,status);create index idx_financial_settlements_date on financial_settlements(settlement_date);
